import{LANDMARKS,QUESTS,currentQuest,createGame,formatTime,interact,landmarkById,migrateGame,movePlayer,nearbyLandmark,rest}from"./shared-rules.js";
const SAVE_KEY="youyi-mosslight-save-v1",$=s=>document.querySelector(s),els={game:$("#game"),player:$("#player"),prompt:$("#interactPrompt"),time:$("#timeLabel"),day:$("#dayLabel"),weather:$("#weatherLabel"),weatherFx:$("#weather"),light:$("#lightShift"),questTitle:$("#questTitle"),questText:$("#questText"),questProgress:$("#questProgress"),energy:$("#energyBar"),energyText:$("#energyText"),dialogue:$("#dialogue"),speaker:$("#speaker"),dialogueTitle:$("#dialogueTitle"),dialogueBody:$("#dialogueBody"),portrait:$("#portrait"),toast:$("#toast"),intro:$("#intro"),canvas:$("#routeCanvas")};
let state=load(),sound=true,started=false,keys=new Set(),autoTarget=null,lastFrame=performance.now(),toastTimer=null,audioCtx=null;
function load(){try{return migrateGame(JSON.parse(localStorage.getItem(SAVE_KEY)))}catch{return createGame()}}
function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(state))}
function beep(note=520,duration=.08,type="sine"){if(!sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=note;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function notify(text){els.toast.textContent=text;els.toast.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>els.toast.classList.remove("show"),1800)}
function render(){const q=currentQuest(state);els.player.style.left=`${state.player.x}%`;els.player.style.top=`${state.player.y}%`;els.time.textContent=formatTime(state);els.day.textContent=`第 ${state.day} 天`;els.weather.textContent=state.weather;els.weatherFx.classList.toggle("rain",state.weather==="细雨");const hour=state.minute/60,night=hour<6||hour>19;els.light.style.opacity=night?.5:Math.max(0,(hour-17)/10);els.questTitle.textContent=q.title;els.questText.textContent=q.summary;els.questProgress.style.width=`${state.quest/(QUESTS.length-1)*100}%`;for(const key of ["letters","dew","wood","herb"])$(`#${key==="letters"?"letter":key}Count`).textContent=state.inventory[key];els.energy.style.width=`${state.player.energy}%`;els.energyText.textContent=state.player.energy;const near=nearbyLandmark(state);els.player.classList.toggle("near",Boolean(near));els.prompt.textContent=near?`E · ${near.name}`:"E";document.querySelectorAll(".hotspot").forEach(node=>{const id=node.dataset.place;node.classList.toggle("target",id===q.target);node.classList.toggle("active",id===near?.id);node.classList.toggle("done",(id==="observatory"&&state.repaired.lens)||(id==="dock"&&state.repaired.bridge))});drawRoute()}
function showDialogue(result){els.speaker.textContent=result.speaker||({collect:"口袋里多了一件东西",hint:"岛屿手记",ending:"苔光广播"}[result.type]||"旅途见闻");els.dialogueTitle.textContent=result.title;els.dialogueBody.textContent=result.body;els.portrait.className=`portrait ${result.speaker==="露卡"?"luca":""}`;els.dialogue.classList.remove("hidden");beep(result.type==="ending"?720:result.type==="collect"?620:460,.12,result.type==="ending"?"triangle":"sine")}
function closeDialogue(){els.dialogue.classList.add("hidden");els.game.focus()}
function doInteract(id=null){if(!started||!els.dialogue.classList.contains("hidden"))return;const outcome=interact(state,id);state=outcome.state;save();render();showDialogue(outcome.result)}
function walkTo(id){const place=landmarkById(id);if(!place)return;autoTarget=place;notify(`循着信光前往${place.name}`);beep(580)}
function tick(now){const delta=Math.min(2.2,(now-lastFrame)/16.67);lastFrame=now;if(started&&els.dialogue.classList.contains("hidden")){let dx=0,dy=0;if(keys.has("ArrowUp")||keys.has("KeyW"))dy--;if(keys.has("ArrowDown")||keys.has("KeyS"))dy++;if(keys.has("ArrowLeft")||keys.has("KeyA"))dx--;if(keys.has("ArrowRight")||keys.has("KeyD"))dx++;if(dx||dy){autoTarget=null;state=movePlayer(state,dx,dy,delta);render()}else if(autoTarget){const dx=autoTarget.x-state.player.x,dy=autoTarget.y-state.player.y;if(Math.hypot(dx,dy)<=Math.max(5.5,autoTarget.r*.72)){const id=autoTarget.id;autoTarget=null;render();setTimeout(()=>doInteract(id),120)}else{state=movePlayer(state,dx,dy,delta);render()}}}requestAnimationFrame(tick)}
function drawRoute(){const canvas=els.canvas,rect=canvas.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}const ctx=canvas.getContext("2d");ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,rect.width,rect.height);const q=currentQuest(state),target=landmarkById(q.target);if(!target)return;const x1=state.player.x/100*rect.width,y1=state.player.y/100*rect.height,x2=target.x/100*rect.width,y2=target.y/100*rect.height,mx=(x1+x2)/2,my=Math.min(y1,y2)-Math.abs(x2-x1)*.08;ctx.beginPath();ctx.moveTo(x1,y1);ctx.quadraticCurveTo(mx,my,x2,y2);ctx.strokeStyle="#fff2a4";ctx.lineWidth=2;ctx.setLineDash([4,9]);ctx.lineDashOffset=-(performance.now()/70)%13;ctx.shadowBlur=10;ctx.shadowColor="#fff3a0";ctx.stroke()}
function showHelp(){showDialogue({type:"hint",title:"如何探索",body:"使用 WASD 或方向键移动，靠近发光地点按 E/空格互动；也可以直接点击地点自动前往。星露和木枝每天只能采集一次，右下角可以回邮局休息到第二天。"})}
document.addEventListener("keydown",event=>{if(["ArrowUp","ArrowDown","ArrowLeft","ArrowRight","Space"].includes(event.code))event.preventDefault();if(event.code==="Escape"&&!els.dialogue.classList.contains("hidden"))return closeDialogue();if((event.code==="KeyE"||event.code==="Space")&&!event.repeat){if(!els.dialogue.classList.contains("hidden"))closeDialogue();else doInteract()}keys.add(event.code)});document.addEventListener("keyup",event=>keys.delete(event.code));window.addEventListener("blur",()=>{keys.clear();save()});window.addEventListener("resize",render);
document.querySelectorAll(".hotspot").forEach(node=>node.onclick=()=>walkTo(node.dataset.place));$("#focusQuest").onclick=()=>walkTo(currentQuest(state).target);$("#dialogueNext").onclick=closeDialogue;$("#helpButton").onclick=showHelp;$("#soundButton").onclick=e=>{sound=!sound;e.currentTarget.textContent=sound?"♪":"×";if(sound)beep(540)};$("#restButton").onclick=()=>{state=rest(state);save();render();showDialogue({type:"story",speaker:"米莫",title:`第 ${state.day} 天 · ${state.weather}`,body:"邮局的木窗透进新一天的光。岛上的露珠和枝条已经重新出现。"})};$("#mobileAction").onclick=()=>doInteract();document.querySelectorAll("[data-dir]").forEach(button=>{const map={up:"ArrowUp",down:"ArrowDown",left:"ArrowLeft",right:"ArrowRight"},code=map[button.dataset.dir];button.addEventListener("pointerdown",e=>{e.preventDefault();keys.add(code)});for(const type of ["pointerup","pointercancel","pointerleave"])button.addEventListener(type,()=>keys.delete(code))});
$("#startButton").onclick=()=>{started=true;els.intro.classList.add("hidden");els.game.focus();beep(420,.12);setTimeout(()=>beep(620,.16),100);notify(state.steps?"欢迎回来，今天的邮路还在等你":"欢迎来到苔光小岛")};
if(state.steps)$("#saveNote").textContent=`继续第 ${state.day} 天 · ${currentQuest(state).title}`;render();requestAnimationFrame(tick);
